from taf.sbts.oam.coam.admin.schemas.procedure.lte_ccm_uplink import LTECCMUplink


class LTECCMUplinkPuschHarqAck(LTECCMUplink):
    def __init__(self, lncel_rdn, measurement_type, reporting_time_interval, reception_subframe,
                 exception_subframe, earfcn, reference_channel, resource_block_offset, root_seq_index=None,
                 prach_cs=None, prach_hs_flag=None, phys_cell_id=None, tdd_frame_conf=None, tdd_spec_subf_conf=None):
        super(LTECCMUplinkPuschHarqAck, self).__init__(lncel_rdn=lncel_rdn,
                                                       measurement_type=measurement_type,
                                                       reporting_time_interval=reporting_time_interval,
                                                       reception_subframe=reception_subframe,
                                                       exception_subframe=exception_subframe,
                                                       earfcn=earfcn,
                                                       root_seq_index=root_seq_index,
                                                       prach_cs=prach_cs,
                                                       prach_hs_flag=prach_hs_flag,
                                                       phys_cell_id=phys_cell_id,
                                                       tdd_frame_conf=tdd_frame_conf,
                                                       tdd_spec_subf_conf=tdd_spec_subf_conf)

        self.pusch_params = {"referenceChannelNumber": self.validate_param('referenceChannelNumber',
                                                                           reference_channel,
                                                                           validity_clause=(reference_channel in [
                                                                               'Invalid', 'A1_1',
                                                                               'A1_2', 'A1_3', 'A1_4',
                                                                               'A1_5', 'A1_6', 'A1_7',
                                                                               'A2_1', 'A2_2', 'A2_3',
                                                                               'A3_1', 'A3_2', 'A3_3',
                                                                               'A3_4', 'A3_5', 'A3_6',
                                                                               'A3_7', 'A4_1', 'A4_2',
                                                                               'A4_3', 'A4_4', 'A4_5',
                                                                               'A4_6', 'A4_7', 'A4_8',
                                                                               'A5_1', 'A5_2', 'A5_3',
                                                                               'A5_4', 'A5_5', 'A5_6',
                                                                               'A5_7', 'A7_1', 'A7_2',
                                                                               'A7_3', 'A7_4', 'A7_5',
                                                                               'A7_6', 'A8_1', 'A8_2',
                                                                               'A8_3', 'A8_4', 'A8_5',
                                                                               'A8_6', 'DCM_1',
                                                                               'DCM_2', 'DCM_3',
                                                                               'DCM_4', 'DCM_5',
                                                                               'DCM_6', 'DCM_7',
                                                                               'DCM_8', 'A14_1',
                                                                               'A15_1', 'A16_2',
                                                                               'A16_3', 'A16_4',
                                                                               'A16_5', 'A17_1',
                                                                               'A17_2', 'A17_3',
                                                                               'A17_4', 'A17_5',
                                                                               'A17_6'])),
                             "resourceBlockOffset": self.validate_param('resourceBlockOffset',
                                                                        resource_block_offset,
                                                                        [0, 99]),
                             }

    @classmethod
    def from_response_dict(cls, response_dict):
        def _get_pusch_param(parameter):
            return response_dict['params']['puschHarqAckParams'][parameter]

        lncel_rdn = response_dict['lncel_rDN']
        measurement_type = response_dict['params']['measurementType']
        reporting_time_interval = response_dict['params']['reportingTimeInterval']
        reception_subframe = response_dict['params']['receptionSubframe']
        exception_subframe = response_dict['params']['expectionSubframe']
        earfcn = response_dict['params']['earfcn']
        root_seq_index = response_dict['params']['rootSeqIndex'] if 'rootSeqIndex' in response_dict['params'] else None
        prach_cs = response_dict['params']['prachCS'] if 'prachCS' in response_dict['params'] else None
        prach_hs_flag = response_dict['params']['prachHsFlag'] if 'prachHsFlag' in response_dict['params'] else None
        phys_cell_id = response_dict['params']['physCellId'] if 'physCellId' in response_dict['params'] else None
        tdd_frame_conf = response_dict['params']['tddFrameConf'] if 'tddFrameConf' in response_dict['params'] else None
        tdd_spec_subf_conf = response_dict['params']['tddSpecSubfConf'] if 'tddSpecSubfConf' in response_dict[
            'params'] else None

        pusch_params = {"referenceChannelNumber": _get_pusch_param('referenceChannelNumber'),
                        "resourceBlockOffset": _get_pusch_param('resourceBlockOffset')}

        return cls(lncel_rdn=lncel_rdn,
                   measurement_type=measurement_type,
                   reporting_time_interval=reporting_time_interval,
                   reception_subframe=reception_subframe,
                   exception_subframe=exception_subframe,
                   earfcn=earfcn,
                   reference_channel=pusch_params["referenceChannelNumber"],
                   resource_block_offset=pusch_params["resourceBlockOffset"],
                   root_seq_index=root_seq_index,
                   prach_cs=prach_cs,
                   prach_hs_flag=prach_hs_flag,
                   phys_cell_id=phys_cell_id,
                   tdd_frame_conf=tdd_frame_conf,
                   tdd_spec_subf_conf=tdd_spec_subf_conf)

    def as_dict(self):
        attributes = super(LTECCMUplinkPuschHarqAck, self).as_dict()
        self.pusch_params = self.filter_empty_parameters(self.pusch_params)
        attributes['params']['puschHarqAckParams'] = self.pusch_params

        return attributes
